#include <numeric>
#include <string>
#include <utility>
#include <vector>

class UnionFind
{
public:
    explicit UnionFind(std::size_t n) : parent_(n), size_(n, 1), components_(n)
    {
        std::iota(parent_.begin(), parent_.end(), std::size_t{ 0 });
    }

    std::size_t find(std::size_t x)
    {
        std::size_t root = x;
        while (parent_[root] != root) root = parent_[root];
        while (parent_[x] != root)
        {
            std::size_t next = parent_[x];
            parent_[x] = root;
            x = next;
        }
        return root;
    }

    bool unite(std::size_t a, std::size_t b)
    {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (size_[a] < size_[b]) std::swap(a, b);
        parent_[b] = a;
        size_[a] += size_[b];
        --components_;
        return true;
    }

    bool connected(std::size_t a, std::size_t b) { return find(a) == find(b); }
    std::size_t sizeOf(std::size_t x) { return size_[find(x)]; }
    std::size_t components() const { return components_; }

private:
    std::vector<std::size_t> parent_, size_;
    std::size_t components_;
};

int countRegions(const std::vector<std::string>& grid)
{
    std::size_t rows = grid.size(), cols = rows ? grid[0].size() : 0;
    UnionFind uf(rows * cols);
    std::size_t cells = 0;
    for (std::size_t r = 0; r < rows; ++r)
        for (std::size_t c = 0; c < cols; ++c)
        {
            if (grid[r][c] != '#') continue;
            ++cells;
            if (r + 1 < rows && grid[r + 1][c] == '#') uf.unite(r * cols + c, (r + 1) * cols + c);
            if (c + 1 < cols && grid[r][c + 1] == '#') uf.unite(r * cols + c, r * cols + c + 1);
        }
    // Every cell starts as its own component; the non-'#' cells stay alone.
    return static_cast<int>(uf.components() - (rows * cols - cells));
}

bool percolates(const std::vector<std::string>& grid)
{
    std::size_t rows = grid.size(), cols = rows ? grid[0].size() : 0;
    if (rows == 0 || cols == 0) return false;
    std::size_t top = rows * cols, bottom = top + 1;
    UnionFind uf(rows * cols + 2);
    for (std::size_t r = 0; r < rows; ++r)
        for (std::size_t c = 0; c < cols; ++c)
        {
            if (grid[r][c] != '.') continue;
            std::size_t id = r * cols + c;
            if (r == 0) uf.unite(id, top);
            if (r == rows - 1) uf.unite(id, bottom);
            if (r + 1 < rows && grid[r + 1][c] == '.') uf.unite(id, id + cols);
            if (c + 1 < cols && grid[r][c + 1] == '.') uf.unite(id, id + 1);
        }
    return uf.connected(top, bottom);
}

int firstCycle(std::size_t n, const std::vector<std::pair<std::size_t, std::size_t>>& edges)
{
    UnionFind uf(n);
    for (std::size_t i = 0; i < edges.size(); ++i)
        if (!uf.unite(edges[i].first, edges[i].second)) return static_cast<int>(i);
    return -1;
}

unitTests:
TEST("uniting") {
    UnionFind uf(10);
    CHECK_EQ(uf.components(), std::size_t{ 10 });
    CHECK(uf.unite(0, 1));
    CHECK(uf.unite(2, 3));
    CHECK(uf.unite(1, 3));
    CHECK(!uf.unite(0, 2));
    CHECK(uf.connected(0, 3));
    CHECK(!uf.connected(0, 4));
    CHECK_EQ(uf.sizeOf(2), std::size_t{ 4 });
    CHECK_EQ(uf.sizeOf(9), std::size_t{ 1 });
    CHECK_EQ(uf.components(), std::size_t{ 7 });
    CHECK_EQ(uf.find(1), uf.find(2));
}
TEST("a million operations") {
    const std::size_t n = 500000;
    UnionFind uf(n);
    for (std::size_t i = 1; i < n; ++i) uf.unite(i - 1, i);          // one long chain, if unbalanced
    CHECK_EQ(uf.components(), std::size_t{ 1 });
    std::size_t same = 0;
    for (std::size_t i = 0; i < n; ++i) same += uf.connected(0, n - 1 - i);
    CHECK_EQ(same, n);
    CHECK_EQ(uf.sizeOf(12345), n);
}
TEST("regions in a grid") {
    CHECK_EQ(countRegions({ "##..#", "#...#", "..#..", "....." , "#.#.#" }), 6);
    CHECK_EQ(countRegions({ "###", "#.#", "###" }), 1);
    CHECK_EQ(countRegions({ "...", "..." }), 0);
    CHECK_EQ(countRegions({}), 0);
    CHECK_EQ(countRegions({ "#.#.#.#" }), 4);
}
TEST("percolation") {
    CHECK(percolates({ ".##", "..#", "#.." }));
    CHECK(!percolates({ ".##", "#.#", "#.." }));
    CHECK(percolates({ "." }));
    CHECK(!percolates({ "#" }));
    CHECK(!percolates({}));
    CHECK(percolates({ "#.#####", "#...###", "###.###", "#...###", "#.#####", "#......" }));
    std::vector<std::string> big(300, std::string(300, '#'));
    for (std::size_t r = 0; r < 300; ++r) big[r][(r / 2) % 300] = '.', big[r][(r / 2 + 1) % 300] = '.';
    CHECK(percolates(big));
    big[150] = std::string(300, '#');
    CHECK(!percolates(big));
}
TEST("the first edge that closes a cycle") {
    CHECK_EQ(firstCycle(4, { { 0, 1 }, { 1, 2 }, { 2, 3 }, { 3, 0 }, { 0, 2 } }), 3);
    CHECK_EQ(firstCycle(3, { { 0, 1 }, { 1, 2 } }), -1);
    CHECK_EQ(firstCycle(2, { { 1, 1 } }), 0);
    CHECK_EQ(firstCycle(5, {}), -1);
}

